ejemplo01.html<pre><code>&lt;h2&gt;What Can JavaScript Do?&lt;/h2&gt;

&lt;p id="demo"&gt;JavaScript &lt;strong&gt;can change&lt;/strong&gt; HTML content.&lt;/p&gt;

&lt;button type="button" 
  onclick='document.getElementById("demo").innerHTML = "Hello JS!"'&gt;
    Click Me!
&lt;/button&gt;
</code></pre>

ejemplo02.html<pre><code>&lt;button 
        onclick="document.getElementById('myImage').src='figuras/pic_bulbon.gif'"&gt;
        Turn on the light
&lt;/button&gt;

&lt;img id="myImage" src="figuras/pic_bulboff.gif" style="width:100px" alt="bombilla"&gt;

&lt;button 
    onclick="document.getElementById('myImage').src='figuras/pic_bulboff.gif'"&gt;
    Turn off the light
&lt;/button&gt;
</code></pre>

ejemplo04.html<pre><code>&lt;button
    type="button" 
    onclick="document.getElementById('demo').style.fontSize='35px'"&gt;
    Click Me!
&lt;/button&gt;
</code></pre>
